M,OAAQ,GAAS,EAAK,OAAS,CAAI,EAC/D,CAEA,SAAS,iBAAwB,CAC/B,IACA,EAAW,OACX,EAAQ,MAAQ,GAChB,EAAgB,MAAQ,GACxB,EAAU,MAAQ,GAClB,EAAiB,MAAQ,GACzB,EAAM,MAAQ,CAAC,CACjB,CAEA,eAAe,cAA8B,CAC3C,UAAU,EACL,EAAQ,OACb,MAAM,WAAW,CAAC,CAAC,MAAM,kBAAkB,CAC7C,CAGA,eAAe,0BAA0C,CACvD,UAAU,EACV,IAAM,EAAe,EAAM,MACvB,GAAU,MAAM,EAAS,UAAY,MAAS,EAC9C,GAAC,eAAe,CAAY,GAAK,CAAC,EAAQ,QAC9C,MAAM,WAAW,CAAC,CAAC,MAAM,kBAAkB,CAC7C,CAEA,eAAe,aAA6B,CAC1C,UAAU,EAER,GAAC,EAAQ,OACT,EAAQ,OACP,EAAU,OAAS,CAAC,EAAW,QAGlC,MAAM,aAAa,CACrB,CAEA,MAAO,CACL,QACA,UACA,YACA,mBACA,aACA,QACA,UACA,eACA,kBACA,cACA,WACA,aACA,yBACA,YACA,eACA,WACA,WACA,eACF,CACF,CAAC","names":[],"ignoreList":[],"sources":["../../src/platform/skills/types.ts","../../src/platform/skills/api/skillsApi.ts","../../src/platform/skills/stores/skillPacksStore.ts"],"sourcesContent":["import type {\n  AgentSkill,\n  AgentSkillPublishRequest\n} from '@comfyorg/ingest-types'\n\n/** The list route returns the user's packs with their full instruction bodies. */\nexport type SkillPack = AgentSkill\n\nexport type SkillPackPublishRequest = AgentSkillPublishRequest\n\n/** `maxLength` from the spec, counted in code points as JSON Schema defines it. */\nexport const MAX_DESCRIPTION_CODE_POINTS = 1024\nexport const MAX_NAME_LENGTH = 64\n\n/** All-dot names are excluded because clients normalize `.` and `..` paths. */\nexport const PACK_NAME_PATTERN = /^[A-Za-z0-9._-]*[A-Za-z0-9_-][A-Za-z0-9._-]*$/\n\n/** Only always-on built-ins are reserved; on-demand built-ins are shadowable. */\nexport const RESERVED_PACK_NAMES = [\n  'building',\n  'comfy-cloud',\n  'canvas-tabs'\n] as const\n\nexport const CONTROL_CHARACTERS = /[\\p{Cc}\\u2028\\u2029]/u\n\nexport function utf8ByteLength(value: string): number {\n  return new TextEncoder().encode(value).length\n}\n\nexport function codePointLength(value: string): number {\n  return Array.from(value).length\n}\n\n/** Description + body, the unit the per-user total-bytes budget is counted in. */\nexport function packByteSize(pack: {\n  description: string\n  body: string\n}): number {\n  return utf8ByteLength(pack.description) + utf8ByteLength(pack.body)\n}\n","import {\n  zAgentSkill,\n  zAgentSkillListResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport { parseErrorResponse } from '@/platform/remote/comfyui/errors'\nimport { api } from '@/scripts/api'\n\nimport type { SkillPack, SkillPackPublishRequest } from '../types'\nimport { MAX_NAME_LENGTH, PACK_NAME_PATTERN } from '../types'\n\n/**\n * 400 is corrective; 409 is capacity. List/publish 404 hides the feature,\n * while delete 404 can also mean the pack is already gone.\n */\nexport class SkillPacksApiError extends Error {\n  constructor(\n    message: string,\n    public readonly status: number\n  ) {\n    super(message)\n    this.name = 'SkillPacksApiError'\n  }\n}\n\n/**\n * Agent responses use `{ error }`; ingest uses the canonical ErrorResponse.\n * Preserve either producer's message, preferring explicit `message` fields.\n */\nasync function toApiError(response: Response): Promise<SkillPacksApiError> {\n  const body: unknown = await response\n    .clone()\n    .json()\n    .catch(() => undefined)\n  if (\n    typeof body === 'object' &&\n    body !== null &&\n    !('message' in body) &&\n    'error' in body &&\n    typeof body.error === 'string'\n  ) {\n    return new SkillPacksApiError(body.error, response.status)\n  }\n  const errorData = await parseErrorResponse(response)\n  return new SkillPacksApiError(errorData.message, response.status)\n}\n\nexport async function listSkillPacks(): Promise<SkillPack[]> {\n  const response = await api.fetchApi('/agent/skills')\n  if (!response.ok) throw await toApiError(response)\n  return zAgentSkillListResponse.parse(await response.json()).skills\n}\n\n/** Publishing an existing name replaces that pack. */\nexport async function publishSkillPack(\n  payload: SkillPackPublishRequest\n): Promise<SkillPack> {\n  const response = await api.fetchApi('/agent/skills', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify(payload)\n  })\n  if (!response.ok) throw await toApiError(response)\n  return zAgentSkill.parse(await response.json())\n}\n\nexport async function deleteSkillPack(name: string): Promise<void> {\n  if (name.length > MAX_NAME_LENGTH || !PACK_NAME_PATTERN.test(name)) {\n    throw new SkillPacksApiError('Invalid skill pack name', 400)\n  }\n  const response = await api.fetchApi(\n    `/agent/skills/${encodeURIComponent(name)}`,\n    { method: 'DELETE' }\n  )\n  if (!response.ok) throw await toApiError(response)\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, watch } from 'vue'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { api } from '@/scripts/api'\n\nimport { reportError } from '@/platform/telemetry/reportError'\n\nimport { listSkillPacks, SkillPacksApiError } from '../api/skillsApi'\nimport type { SkillPack } from '../types'\n\nconst AGENT_EXPERIENCE_FLAG = 'agent-in-app-experience'\nconst SKILL_PACKS_FLAG = 'agent-skill-packs'\n\nfunction isRoutesUnavailable(error: unknown): boolean {\n  return error instanceof SkillPacksApiError && error.status === 404\n}\n\nexport const useSkillPacksStore = defineStore('skillPacks', () => {\n  const packs = ref<SkillPack[]>([])\n  const loading = ref(false)\n  const hasLoaded = ref(false)\n  // CRUD can populate a partial cache; only a full listing proves absence.\n  // Refreshes keep the last confirmation until a response replaces it.\n  const catalogConfirmed = ref(false)\n  const loadFailed = ref(false)\n  const flagsEnabled = ref(false)\n  // Disabled backend gates answer 404, independently of PostHog flags.\n  const routesAvailable = ref(true)\n\n  const enabled = computed(() => flagsEnabled.value && routesAvailable.value)\n\n  let flagGateStarted = false\n  let fetchGeneration = 0\n  let inFlight: Promise<void> | undefined\n  let catalogRequested = false\n  const { resolvedUserInfo } = useCurrentUser()\n  const workspace = useTeamWorkspaceStore()\n  function currentScope(): string {\n    return JSON.stringify([\n      location.origin,\n      api.apiURL('/agent/skills'),\n      resolvedUserInfo.value?.id ?? null,\n      workspace.workspaceId ?? null\n    ])\n  }\n  const scope = ref(currentScope())\n\n  function invalidateCatalog(): void {\n    fetchGeneration++\n    inFlight = undefined\n    packs.value = []\n    loading.value = false\n    hasLoaded.value = false\n    catalogConfirmed.value = false\n    loadFailed.value = false\n    routesAvailable.value = true\n  }\n\n  watch(\n    currentScope,\n    (next) => {\n      scope.value = next\n      invalidateCatalog()\n      if (catalogRequested && flagsEnabled.value && resolvedUserInfo.value)\n        void ensurePacks()\n    },\n    { flush: 'sync' }\n  )\n\n  async function startFlagGate({\n    fetch = true\n  }: { fetch?: boolean } = {}): Promise<void> {\n    catalogRequested ||= fetch\n    if (flagGateStarted) {\n      if (fetch && flagsEnabled.value) {\n        if (!routesAvailable.value) void fetchPacks().catch(reportFetchFailure)\n        else void ensurePacks()\n      }\n      return\n    }\n    flagGateStarted = true\n    try {\n      const { default: posthog } = await import('posthog-js')\n      const sync = () => {\n        const wasEnabled = flagsEnabled.value\n        flagsEnabled.value =\n          posthog.isFeatureEnabled(AGENT_EXPERIENCE_FLAG) === true &&\n          posthog.isFeatureEnabled(SKILL_PACKS_FLAG) === true\n        if (wasEnabled && !flagsEnabled.value) invalidateCatalog()\n        // Probe because backend availability can disagree with PostHog.\n        if (!wasEnabled && flagsEnabled.value && catalogRequested) {\n          void fetchPacks().catch(reportFetchFailure)\n        }\n      }\n      posthog.onFeatureFlags((_flags, _variants, context) => {\n        // Ignore failed flag deliveries.\n        if (context?.errorsLoading) return\n        sync()\n      })\n      sync()\n    } catch (error) {\n      flagGateStarted = false\n      reportError(error, {\n        errorType: 'agent_skill_packs_flag_gate_failure',\n        surface: 'agent'\n      })\n    }\n  }\n\n  function reportFetchFailure(error: unknown): void {\n    reportError(error, {\n      errorType: 'error_fetching_agent_skill_packs',\n      surface: 'agent'\n    })\n  }\n\n  function syncScope(): void {\n    const next = currentScope()\n    if (scope.value === next) return\n    scope.value = next\n    invalidateCatalog()\n  }\n\n  function fetchPacks(): Promise<void> {\n    syncScope()\n    catalogRequested = true\n    if (inFlight) return inFlight\n    const request = fetchPacksOnce().finally(() => {\n      if (inFlight === request) inFlight = undefined\n    })\n    inFlight = request\n    return request\n  }\n\n  function isCurrentScope(requestScope: string): boolean {\n    syncScope()\n    return requestScope === scope.value\n  }\n\n  // Syncs first: a backend change has no reactive source, so a response may be\n  // the first to notice it and must move the store to the new scope.\n  function isSuperseded(generation: number, requestScope: string): boolean {\n    return !isCurrentScope(requestScope) || generation !== fetchGeneration\n  }\n\n  function applyCatalog(nextPacks: SkillPack[]): void {\n    packs.value = nextPacks\n    hasLoaded.value = true\n    catalogConfirmed.value = true\n    routesAvailable.value = true\n  }\n\n  async function fetchPacksOnce(): Promise<void> {\n    const generation = ++fetchGeneration\n    const requestScope = scope.value\n    loading.value = true\n    loadFailed.value = false\n    try {\n      const nextPacks = await listSkillPacks()\n      if (isSuperseded(generation, requestScope)) return\n      applyCatalog(nextPacks)\n    } catch (error) {\n      if (isSuperseded(generation, requestScope)) return\n      if (isRoutesUnavailable(error)) {\n        markUnavailable()\n        return\n      }\n      loadFailed.value = true\n      throw error\n    } finally {\n      if (generation === fetchGeneration) loading.value = false\n    }\n  }\n\n  function upsertPack(pack: SkillPack, requestScope = scope.value): void {\n    syncScope()\n    if (requestScope !== scope.value) return\n    fetchGeneration++\n    inFlight = undefined\n    loading.value = false\n    hasLoaded.value = true\n    loadFailed.value = false\n    const rest = packs.value.filter((existing) => existing.name !== pack.name)\n    packs.value = [...rest, pack].sort((a, b) => a.name.localeCompare(b.name))\n  }\n\n  function removePack(name: string, requestScope = scope.value): void {\n    syncScope()\n    if (requestScope !== scope.value) return\n    fetchGeneration++\n    inFlight = undefined\n    loading.value = false\n    packs.value = packs.value.filter((pack) => pack.name !== name)\n  }\n\n  function markUnavailable(): void {\n    fetchGeneration++\n    inFlight = undefined\n    loading.value = false\n    routesAvailable.value = false\n    hasLoaded.value = false\n    catalogConfirmed.value = false\n    packs.value = []\n  }\n\n  async function refreshPacks(): Promise<void> {\n    syncScope()\n    if (!enabled.value) return\n    await fetchPacks().catch(reportFetchFailure)\n  }\n\n  // Lists after any in-flight request, so the result covers earlier changes.\n  async function refreshPacksInBackground(): Promise<void> {\n    syncScope()\n    const requestScope = scope.value\n    if (inFlight) await inFlight.catch(() => undefined)\n    if (!isCurrentScope(requestScope) || !enabled.value) return\n    await fetchPacks().catch(reportFetchFailure)\n  }\n\n  async function ensurePacks(): Promise<void> {\n    syncScope()\n    if (\n      !enabled.value ||\n      loading.value ||\n      (hasLoaded.value && !loadFailed.value)\n    )\n      return\n    await refreshPacks()\n  }\n\n  return {\n    packs,\n    loading,\n    hasLoaded,\n    catalogConfirmed,\n    loadFailed,\n    scope,\n    enabled,\n    flagsEnabled,\n    routesAvailable,\n    startFlagGate,\n    fetchPacks,\n    refreshPacks,\n    refreshPacksInBackground,\n    ensurePacks,\n    isCurrentScope,\n    upsertPack,\n    removePack,\n    markUnavailable\n  }\n})\n"],"file":"skillPacksStore-CPFgKMTm.js"}"""

